/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );


// VARIABLES //

var debug = logger( 'plot:view:browser:router' );
var RE_HAS_PARAMS = /:/;


// FUNCTIONS //

/**
* Sends a 404 response.
*
* @private
* @param {IncomingMessage} request - HTTP request object
* @param {ServerResponse} response - HTTP response object
*/
function notFound( request, response ) {
	debug( 'Sending 404 response...' );
	response.statusCode = 404;
	response.end();
}

/**
* Converts a parameterized URL to a route object.
*
* @private
* @param {string} url - input URL
* @returns {Object} route object
*/
function parameterize( url ) {
	var parts;
	var names;
	var re;
	var p;
	var i;

	// WARN: the following is a naive implementation which assumes simple parameterized URLs (e.g., `/foo/bar/:beep/:boop/biz`)

	parts = url.split( '/' );
	names = [];
	for ( i = 0; i < parts.length; i++ ) {
		p = parts[ i ];
		if ( p[ 0 ] === ':' ) {
			names.push( p.substring( 1 ) );
			parts[ i ] = '([^/]+)';
		}
	}
	re = parts.join( '/' );
	if ( re[ 0 ] === '/' ) {
		re = '\\' + re;
	}
	if ( re[ re.length-1 ] === '/' ) {
		re = re.substring( re.length-1 ) + '\\/';
	}
	re = '^' + re + '$';
	return {
		'regexp': new RegExp( re ),
		'names': names
	};
}


// MAIN //

/**
* Router constructor.
*
* @private
* @constructor
* @returns {Router} router instance
*/
function Router() {
	if ( !( this instanceof Router ) ) {
		return new Router();
	}
	setNonEnumerableReadOnly( this, '_routes', {
		'GET': [],
		'POST': []
	});
	return this;
}

/**
* Registers a route.
*
* @name route
* @memberof Router.prototype
* @type {Function}
* @param {Object} schema - route schema
* @returns {Router} router instance
*/
setNonEnumerableReadOnly( Router.prototype, 'route', function route( schema ) {
	var type;
	var url;

	debug( 'Registering a new route: %s %s', schema.method, schema.url );
	if ( RE_HAS_PARAMS.test( schema.url ) ) {
		type = 'params';
		url = parameterize( schema.url );
	} else {
		type = 'path';
		url = schema.url;
	}
	this._routes[ schema.method ].push( [ type, url, schema.handler ] );
	return this;
});

/**
* Resolves a request handler.
*
* @name resolve
* @memberof Router.prototype
* @type {Function}
* @param {IncomingMessage} request - HTTP request object
* @returns {Function} request handler
*/
setNonEnumerableReadOnly( Router.prototype, 'resolve', function resolve( request ) {
	var method;
	var names;
	var match;
	var table;
	var entry;
	var url;
	var fcn;
	var i;
	var j;

	method = request.method;
	url = request.url;

	// Initialize an object for storing route parameters:
	request.params = {};

	debug( 'Resolving request handler for %s %s', method, url );
	table = this._routes[ method ];
	if ( !table ) {
		debug( 'Unable to resolve request handler.' );
		return notFound;
	}
	for ( i = 0; i < table.length; i++ ) {
		entry = table[ i ];

		// Case: URL matches an exact route path
		if ( entry[ 0 ] === 'path' ) {
			if ( url === entry[ 1 ] ) {
				fcn = entry[ 2 ];
				break;
			}
		}
		// Case: URL matches a parameterized route
		else if ( entry[ 0 ] === 'params' ) {
			match = url.match( entry[ 1 ].regexp );
			if ( match ) {
				names = entry[ 1 ].names;
				for ( j = 0; j < names.length; j++ ) {
					request.params[ names[ j ] ] = match[ j+1 ];
				}
				fcn = entry[ 2 ];
				break;
			}
		}
	}
	if ( !fcn ) {
		debug( 'Unable to resolve request handler.' );
		return notFound;
	}
	debug( 'Successfully resolved request handler.' );
	return fcn;
});


// EXPORTS //

module.exports = Router;
